import os
import time
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def poll_transcription_job(
    job_name: str,
    *,
    poll_interval_seconds: float = 5.0,
    timeout_seconds: float = 3600.0,
    aws_region: Optional[str] = None,
) -> str:
    """
    Poll an Amazon Transcribe job until it completes and return the transcript text.

    Requirements:
        - AWS credentials available via boto3 standard configuration
        - Either set aws_region or AWS_DEFAULT_REGION/AWS_REGION in the environment
    """
    region = aws_region or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    if not region:
        raise ValueError("AWS region must be provided via aws_region, AWS_REGION, or AWS_DEFAULT_REGION.")

    client = boto3.client("transcribe", region_name=region)
    deadline = time.time() + timeout_seconds

    while True:
        if time.time() > deadline:
            raise TimeoutError(f"Timed out waiting for transcription job '{job_name}' to complete.")

        try:
            resp: Dict[str, Any] = client.get_transcription_job(TranscriptionJobName=job_name)
        except (BotoCoreError, ClientError) as exc:
            raise RuntimeError(f"Failed to poll transcription job '{job_name}': {exc}") from exc

        job = resp.get("TranscriptionJob", {})
        status = job.get("TranscriptionJobStatus")

        if status == "COMPLETED":
            transcript_uri = (
                job.get("Transcript", {}) or {}
            ).get("TranscriptFileUri")
            if not transcript_uri:
                raise RuntimeError(f"Transcription job '{job_name}' completed without a transcript URI.")

            try:
                import urllib.request
                import json
            except Exception as exc:
                raise RuntimeError(f"Failed to import transcript fetch dependencies: {exc}") from exc

            try:
                with urllib.request.urlopen(transcript_uri) as response:
                    payload = json.loads(response.read().decode("utf-8"))
            except Exception as exc:
                raise RuntimeError(f"Failed to fetch transcript from '{transcript_uri}': {exc}") from exc

            results = payload.get("results", {})
            transcripts = results.get("transcripts", [])
            if not transcripts:
                return ""

            return "\n".join(
                t.get("transcript", "")
                for t in transcripts
                if isinstance(t, dict) and t.get("transcript")
            )

        if status == "FAILED":
            failure_reason = job.get("FailureReason", "Unknown failure")
            raise RuntimeError(f"Transcription job '{job_name}' failed: {failure_reason}")

        time.sleep(poll_interval_seconds)
